const LINDUNG_SEO_HTML="<!doctype html><html lang=\"ms\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>SEO Command Center \u00b7 Takaful LINDUNG</title><style>\n:root{--navy:#101f36;--blue:#155eef;--mut:#52647c;--line:#d4deeb}*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:var(--navy);font:15px/1.6 system-ui}main{max-width:1120px;margin:auto;padding:18px 16px 100px}a{color:#155eef}h1{font-size:clamp(25px,5vw,36px);line-height:1.15;letter-spacing:-.04em}h2{font-size:21px}header{padding:24px;border-radius:22px;background:var(--navy);color:white;margin:18px 0}header p{color:#dfebfa}.tabs,.actions{display:flex;gap:9px;overflow-x:auto;overscroll-behavior-x:contain;padding:7px 0}.tabs button{white-space:nowrap;flex:none}.tabs button.on,button.primary{background:var(--blue);color:white;border-color:var(--blue)}button,input,select,textarea{font:inherit;border:1px solid #aebed2;border-radius:11px;min-height:46px;padding:10px 13px;background:white;color:var(--navy);max-width:100%}button{font-weight:700;cursor:pointer}button:disabled{opacity:.5}input,select,textarea{width:100%;margin:7px 0 12px}textarea{min-height:130px;resize:vertical}label{display:block;font-weight:650}button:focus-visible,a:focus-visible{outline:3px solid #7daaff;outline-offset:3px}.card{padding:20px;border:1px solid var(--line);border-radius:18px;background:white;margin:15px 0;min-width:0}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.metric b{display:block;font-size:31px}.metric small,.muted{color:var(--mut)}.row{padding:15px 0;border-top:1px solid var(--line);overflow-wrap:anywhere}.row h3{margin:0}.chip{display:inline-block;background:#eaf0fa;padding:4px 10px;border-radius:100px;font-size:12px;margin:5px}.notice{padding:14px;background:#e6f3ee;border:1px solid #b1d9c6;border-radius:12px;margin:14px 0;white-space:pre-wrap}.bad{background:#fff1ec;border-color:#e0b7a5;color:#952f19}.hidden{display:none!important}.back{min-height:44px;display:inline-flex;align-items:center}.checks{display:flex;gap:8px;align-items:center}.checks input{width:22px;margin:0}.dialog{position:fixed;inset:0;background:#101f3680;z-index:10;overflow:auto;padding:20px}.dialog>.card{max-width:850px;margin:20px auto}pre{white-space:pre-wrap;overflow-wrap:anywhere}#view{min-height:200px}#status:empty{display:none}@media(max-width:650px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.dialog{padding:6px}.card{padding:16px}.actions{flex-wrap:wrap}header{padding:20px}}\n</style></head><body><main><a class=\"back\" href=\"/takaful-keluarga?module=dashboard\">\u2190 Dashboard Takaful Keluarga</a><header><small>KERJA SENDIRI \u00b7 OWNER</small><h1>SEO Command Center</h1><p>Takaful LINDUNG \u2014 research \u2192 draf \u2192 semak \u2192 lulus \u2192 terbit.</p></header><div class=\"card\"><b>https://bijakbelanja.com/lindung/</b><p class=\"muted\">Sumber produk daripada knowledge diluluskan. Blog BM dan English. Kelulusan pemilik diperlukan sebelum penerbitan.</p><a href=\"https://bijakbelanja.com/lindung/blog/\" target=\"_blank\" rel=\"noopener\">Buka blog awam \u2197</a></div><nav id=\"tabs\" class=\"tabs\" aria-label=\"Modul SEO\"></nav><div id=\"status\" role=\"status\" class=\"notice\"></div><div id=\"view\">Menghubungkan sesi owner\u2026</div></main><div id=\"dialog\" class=\"dialog hidden\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Editor artikel\"></div><script src=\"/ks-session-sync.js\"></script><script>\n(()=>{'use strict';const $=x=>document.getElementById(x),PUB='sb_publishable_62EhJqrdhyxXVPLkWfOFhg_utP6FD6s',KEY='rc4.sess';const labels={overview:'Ringkasan',keywords:'Keyword',competitors:'Pesaing',posts:'Artikel',gsc:'Search Console',links:'Pautan balik',report:'Laporan'};let jwt=null,tab=new URL(location.href).searchParams.get('tab')||'overview',posts=[],keywords=[],loading=false;const esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const dt=x=>x?new Date(x).toLocaleString('ms-MY',{timeZone:'Asia/Kuala_Lumpur'}):'\u2014';\nfunction notice(t,bad=false){$('status').textContent=t;$('status').className='notice'+(bad?' bad':'')}\nasync function auth(){let r0;try{r0=JSON.parse(sessionStorage.getItem(KEY)||'null')?.r}catch{}if(!r0)throw Error('Sesi owner diperlukan. Log masuk melalui dashboard Kerja Sendiri.');const r=await fetch('/api/supabase/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:PUB,'content-type':'application/json'},body:JSON.stringify({refresh_token:r0})});const j=await r.json();if(!r.ok||!j.access_token)throw Error('Sesi tamat. Log masuk semula di dashboard.');jwt=j.access_token;sessionStorage.setItem(KEY,JSON.stringify({r:j.refresh_token}));window.ksSessionSync?.rotated(j.refresh_token)}\nasync function api(a,p={}){const r=await fetch('/api/supabase/functions/v1/ks-ilindung-persona',{method:'POST',headers:{authorization:'Bearer '+jwt,apikey:PUB,'content-type':'application/json'},body:JSON.stringify({action:'seo',seo_action:a,payload:p}),signal:AbortSignal.timeout(180000)});const j=await r.json();if(!r.ok||j.error)throw Error(j.error||'HTTP '+r.status);return j}\nconst button=(t,a,id='')=>`<button data-a=\"${a}\" data-id=\"${esc(id)}\">${t}</button>`;const card=(h,t)=>`<section class=\"card\"><h2>${h}</h2>${t}</section>`;const metric=(h,n)=>`<div class=\"card metric\"><small>${h}</small><b>${esc(n)}</b></div>`;\nasync function load(){loading=true;$('tabs').innerHTML=Object.entries(labels).map(([k,v])=>`<button data-tab=\"${k}\" class=\"${k===tab?'on':''}\">${v}</button>`).join('');$('view').textContent='Membaca data live\u2026';try{let html='';if(tab==='overview'||tab==='report'){const j=await api('overview');html=`<div class=\"grid\">${metric('Diterbitkan',j.published)+metric('Draf',j.drafts)+metric('Keyword',j.keywords)+metric('Klik GSC','\u2014')}</div>`+card('Langkah seterusnya','<p>Tambah atau luluskan keyword, jana artikel, semak fakta dan terbitkan selepas kelulusan.</p>'+button('Ke Keyword','keywords')+button('Ke Artikel','posts'))+card(tab==='report'?'Log aktiviti SEO':'Artikel terbaru',tab==='report'?j.audit.map(r=>`<div class=\"row\"><b>${esc(r.action)}</b><small> \u00b7 ${dt(r.ts)}</small></div>`).join(''):j.posts.slice(0,8).map(r=>`<div class=\"row\"><b>${esc(r.title)}</b> <span class=\"chip\">${esc(r.lang)} \u00b7 ${esc(r.status)}</span></div>`).join(''));}\nif(tab==='keywords'){const j=await api('keywords');keywords=j.rows;html=card('Research keyword',`<p class=\"muted\">Cadangan AI dilabel dengan jelas. Volum carian tidak direka.</p>${button('Cari keyword dengan AI','keyword_research')}<form data-form=\"keyword_add\"><label>Keyword<input name=\"keyword\" required minlength=\"2\" maxlength=\"180\" placeholder=\"Contoh: takaful keluarga guna simpanan persaraan\"></label><button class=\"primary\">Tambah</button></form>`)+card('Senarai keyword',keywords.map(r=>`<div class=\"row\"><b>${esc(r.payload.keyword)}</b><span class=\"chip\">${esc(r.payload.status)}</span><p class=\"muted\">${esc(r.payload.source)} \u00b7 Volum tidak diketahui</p>${r.payload.status==='candidate'?button('Luluskan','keyword_approve',r.id):''}${r.payload.status==='approved'?button('Buat artikel','from_keyword',r.id):''}${button('Kecualikan','keyword_exclude',r.id)}</div>`).join('')||'<p>Belum ada keyword.</p>');}\nif(tab==='posts'){const [j,k]=await Promise.all([api('posts'),api('keywords')]);posts=j.rows;keywords=k.rows;const approved=keywords.filter(r=>r.payload.status==='approved');html=card('Jana artikel blog',`<form data-form=\"generate\"><label>Keyword diluluskan<select name=\"keyword_id\" required><option value=\"\">Pilih keyword</option>${approved.map(r=>`<option value=\"${r.id}\">${esc(r.payload.keyword)}</option>`).join('')}</select></label><label>Tajuk / topik<input name=\"topic\" minlength=\"5\" maxlength=\"200\" required></label><label>Sudut artikel<input name=\"angle\" maxlength=\"120\"></label><label>Bahasa<select name=\"lang\"><option value=\"ms\">Bahasa Melayu</option><option value=\"en\">English</option><option value=\"both\">Kedua-duanya</option></select></label><button class=\"primary\" ${!approved.length?'disabled':''}>Jana draf AI</button></form><p class=\"muted\">AI menggunakan sumber knowledge diluluskan. Draf tidak diterbitkan secara automatik.</p>`)+card('Artikel & jadual',button('Terbitkan jadual yang sudah sampai masa','run_due')+'<p class=\"muted\">Waktu Malaysia. Penerbitan jadual dijalankan apabila butang ini ditekan.</p>'+posts.map(r=>`<div class=\"row\"><h3>${esc(r.title)}</h3><span class=\"chip\">${esc(r.lang)} \u00b7 ${esc(r.status)} \u00b7 v${r.revision}</span><p class=\"muted\">Dikemas kini ${dt(r.updated_at)}</p><div class=\"actions\">${button('Buka / semak','edit',r.id)}${r.status==='published'?`<a href=\"https://bijakbelanja.com/lindung${r.lang==='en'?'/en':''}/blog/${encodeURIComponent(r.slug)}/\" target=\"_blank\" rel=\"noopener\">Lihat awam</a>`:''}</div>${j.scheduled.filter(s=>s.payload.post_id===r.id).map(s=>`<p class=\"muted\">Jadual: ${dt(s.payload.scheduled_at)} \u00b7 ${esc(s.payload.status)}</p>`).join('')}</div>`).join(''));}\nif(tab==='gsc'){const j=await api('gsc');html=card('Google Search Console',`<p>Status: ${j.connected?'Data disambungkan':'Belum disambungkan / belum disegerakkan'}</p><form data-form=\"gsc_set\"><label>Property yang telah disahkan<input name=\"property\" required value=\"${esc(j.property||'https://bijakbelanja.com/lindung/')}\"></label><button>Sahkan & sambungkan property</button></form>${button('Segerakkan 28 hari','gsc_sync')}<p class=\"muted\">Property mesti disahkan di GSC dan service account SEO sedia ada perlu diberi akses. Data ditapis hanya untuk /lindung/.</p><label>Sitemap<input readonly value=\"https://bijakbelanja.com/sitemap.xml\"></label><a target=\"_blank\" rel=\"noopener\" href=\"https://search.google.com/search-console\">Buka Google Search Console \u2197</a>${j.totals?`<div class=\"grid\">${metric('Klik',j.totals.clicks)}${metric('Impresi',j.totals.impressions)}${metric('Posisi',j.totals.position??'\u2014')}</div>`:''}`);}\nif(tab==='competitors'){const j=await api('competitors');html=card('Tambah pesaing / sumber perbandingan','<form data-form=\"competitor_add\"><label>Domain awam HTTPS<input name=\"hostname\" required placeholder=\"prubsn.com.my\"></label><button>Tambah</button></form><p class=\"muted\">Semakan sitemap sebenar. Tiada anggaran authority atau trafik.</p>')+card('Sitemap pesaing',j.rows.map(r=>`<div class=\"row\"><b>${esc(r.payload.hostname)}</b><p class=\"muted\">${r.payload.url_count??'\u2014'} URL \u00b7 ${dt(r.payload.checked_at)}</p>${button('Analisis sitemap','competitor_analyze',r.id)}<details><summary>URL ditemui</summary>${(r.payload.urls||[]).slice(0,40).map(u=>`<p>${esc(u)}</p>`).join('')}</details></div>`).join(''));}\nif(tab==='links'){const j=await api('links');html=card('Peluang pautan balik','<form data-form=\"link_add\"><label>URL halaman HTTPS<input name=\"page_url\" type=\"url\" required></label><label>Kenapa relevan<textarea name=\"rationale\" maxlength=\"500\"></textarea></label><button>Tambah</button></form>')+card('Semakan pautan',j.rows.map(r=>`<div class=\"row\"><b>${esc(r.payload.page_url)}</b><span class=\"chip\">${esc(r.payload.status)}</span><p>${esc(r.payload.rationale)}</p>${button('Sahkan pautan ke LINDUNG','link_verify',r.id)}</div>`).join(''));}$('view').innerHTML=html;}catch(e){notice(e.message,true);$('view').innerHTML=card('Sambungan belum berjaya',button('Cuba lagi','reload'));}finally{loading=false}}\nfunction edit(id){const p=posts.find(x=>x.id===id);if(!p)return;const fields=['title','seo_title','description','body_html'];$('dialog').innerHTML=card('Semak artikel',button('Tutup','close')+`<form data-form=\"save_post\"><input type=\"hidden\" name=\"id\" value=\"${p.id}\"><input type=\"hidden\" name=\"revision\" value=\"${p.revision}\">${fields.map(k=>`<label>${esc(k)}${k==='body_html'||k==='description'?`<textarea name=\"${k}\" ${k==='body_html'?'style=\"min-height:260px\"':''}>${esc(p[k])}</textarea>`:`<input name=\"${k}\" value=\"${esc(p[k])}\">`}</label>`).join('')}<button ${p.status!=='draft'?'disabled':''}>Simpan draf</button></form><p class=\"muted\">Suntingan membatalkan kelulusan lama. Kandungan HTML ditapis pada blog awam.</p><div id=\"review\" class=\"notice\">Semak fakta dahulu sebelum meluluskan.</div><div class=\"actions\">${button('Semak fakta & sumber','review',id)}${button('Luluskan fakta','approve',id)}${button('Terbit sekarang','publish',id)}${button('Tarik balik ke draf','reopen',id)}</div><label class=\"checks\"><input id=\"facts\" type=\"checkbox\">Saya sudah semak fakta berdasarkan dokumen rasmi.</label><form data-form=\"schedule\"><input type=\"hidden\" name=\"id\" value=\"${p.id}\"><label>Tarikh dan masa Malaysia<input name=\"when\" type=\"datetime-local\" required></label><button>Jadualkan artikel diluluskan</button></form><p class=\"muted\">Jadual diterbitkan melalui butang \u201cTerbitkan jadual yang sudah sampai masa\u201d.</p>`);$('dialog').classList.remove('hidden')}\nasync function run(a,p={},el){if(el)el.disabled=true;notice('Memproses\u2026');try{const j=await api(a,p);if(a==='review'){$('review').textContent=(j.issues.length?'Perlu dibaiki: '+j.issues.join('; '):'Semakan asas lulus. Pemilik perlu semak kesahihan fakta.')+'\\nSumber: '+j.sources.map(x=>x.title).join('; ');return}notice('Berjaya.'+(j.posts?' '+j.posts.length+' draf disimpan.':''));if(a==='save_post'||a==='reopen')$('dialog').classList.add('hidden');await load();return j}catch(e){notice(e.message,true);if($('review'))$('review').textContent=e.message}finally{if(el)el.disabled=false}}\ndocument.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.tab){tab=t.dataset.tab;history.pushState({},'', '?tab='+tab);notice('');return load()}const a=t.dataset.a,id=t.dataset.id;if(!a)return;if(a==='close')return $('dialog').classList.add('hidden');if(a==='edit')return edit(id);if(a==='reload')return load();if(['keywords','posts'].includes(a)){tab=a;return load()}if(a==='from_keyword'){tab='posts';await load();const f=document.querySelector('[data-form=\"generate\"]');f.keyword_id.value=id;f.topic.value=keywords.find(x=>x.id===id)?.payload.keyword||'';return}if(a==='keyword_approve'||a==='keyword_exclude')return run('keyword_status',{id,status:a==='keyword_approve'?'approved':'excluded'},t);if(a==='publish'&&!confirm('Terbitkan artikel ini ke blog awam LINDUNG?'))return;if(a==='approve')return run(a,{id,facts_confirmed:$('facts').checked},t);return run(a,{id},t)});\ndocument.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const a=f.dataset.form,p=Object.fromEntries(new FormData(f));if(a==='schedule'){p.scheduled_at=new Date(p.when+':00+08:00').toISOString();delete p.when;}await run(a,p,f.querySelector('button'))});window.addEventListener('popstate',()=>{tab=new URL(location.href).searchParams.get('tab')||'overview';load()});window.ksSessionSync?.on(m=>{if(m.t==='logout'){jwt=null;notice('Sesi tamat.',true);$('view').textContent='Log masuk semula melalui dashboard.'}});auth().then(load).catch(e=>{notice(e.message,true);$('view').innerHTML='<a href=\"/\">Ke dashboard Kerja Sendiri</a>'});})();\n</script></body></html>\n";
