const KS_SESSION_SYNC_V1="/* Kerja Sendiri | Shared session sync V1 (owner single login).\n * Problem fixed: Supabase rotates the refresh token on every refresh and revokes the WHOLE session when an\n * already-rotated token is reused. The dashboard kept its refresh token only in memory, so after the AI\n * Command Center (same tab after Back/bfcache, or a second tab) rotated it, the dashboard's next refresh\n * reused the stale token and the owner was logged out everywhere.\n * Fix: before any refresh the dashboard adopts the newest token of this tab (sessionStorage rc4.sess), and\n * every page announces rotations/logout to other open tabs of this origin with BroadcastChannel.\n * Nothing is written to localStorage, cookies, URLs or logs. Backend checks (ai_is_owner, admin) are unchanged.\n */\n(function(){\n'use strict';\nif(window.ksSessionSync)return;\nvar KEY='rc4.sess',ch=null,listeners=[],last=null;\ntry{ch=new BroadcastChannel('ks-session-v1')}catch(_){ch=null}\nfunction read(){try{var d=JSON.parse(sessionStorage.getItem(KEY)||'null');return d&&typeof d.r==='string'&&d.r.length?d.r:null}catch(_){return null}}\nfunction write(r){try{sessionStorage.setItem(KEY,JSON.stringify({r:r}))}catch(_){}}\nfunction clear(){try{sessionStorage.removeItem(KEY)}catch(_){}}\nfunction post(m){if(ch)try{ch.postMessage(m)}catch(_){}}\nvar api={\n read:read,\n rotated:function(r){if(typeof r!=='string'||!r||r===last)return;last=r;write(r);post({t:'rotated',r:r})},\n loggedOut:function(){last=null;clear();post({t:'logout'})},\n on:function(fn){listeners.push(fn)}\n};\nif(ch)ch.onmessage=function(e){\n var m=e&&e.data;if(!m||typeof m!=='object')return;\n if(m.t==='rotated'&&typeof m.r==='string'&&m.r.length&&m.r.length<4096){\n  if(!read())return;           // a signed-out tab never gains a session from another tab\n  last=m.r;write(m.r);\n }else if(m.t==='logout'){last=null;clear()}\n else return;\n listeners.forEach(function(fn){try{fn(m)}catch(_){}});\n};\nwindow.ksSessionSync=api;\n\n// ---- dashboard integration (index.html + platform.js + rc4.js). Absent on other pages.\nif(typeof state==='undefined'||typeof access!=='function')return;\nvar desc=Object.getOwnPropertyDescriptor(state,'session');\nif(desc&&desc.set&&desc.get){\n Object.defineProperty(state,'session',{configurable:true,enumerable:true,get:desc.get,set:function(v){desc.set.call(state,v);if(v&&v.refresh_token)api.rotated(v.refresh_token)}});\n}\nvar prevAccess=access;\naccess=async function(){\n // Adopt the newest refresh token of this tab before Supabase is asked for a new access token.\n var s=state.session,r=read();\n if(s&&r&&r!==s.refresh_token)state.session=Object.assign({},s,{refresh_token:r,expires_at:0});\n return prevAccess.apply(this,arguments);\n};\napi.on(function(m){\n if(m.t==='rotated'&&state.session&&state.session.refresh_token!==m.r)state.session=Object.assign({},state.session,{refresh_token:m.r,expires_at:0});\n if(m.t==='logout'&&state.session&&typeof clearSession==='function')clearSession();\n});\nvar lo=document.getElementById('logout');\nif(lo)lo.addEventListener('click',function(){api.loggedOut()},true);\n// Page restored from the back/forward cache: memory may hold a token that another page already rotated.\nwindow.addEventListener('pageshow',function(e){\n if(!e.persisted||!state.session)return;\n var r=read();if(!r){if(typeof clearSession==='function')clearSession();return}\n if(r!==state.session.refresh_token)state.session=Object.assign({},state.session,{refresh_token:r,expires_at:0});\n});\n})();\n";
const UNIFIED_DASHBOARD_THEME_V1="/* Kerja Sendiri | Unified Dashboard UI V1 — light, accessible, mobile-first.\n * Scoped to owner dashboards; public landing (#landing) intentionally excluded.\n * A design-language layer, not an authentication or business-logic change.\n */\n:root {\n  --cc-bg:#f4f6fa; --cc-panel:#ffffff; --cc-ink:#101f36;\n  --cc-muted:#475569; --cc-line:#cfd7e4; --cc-soft:#edf2f8;\n  --cc-navy:#101f36; --cc-blue:#155eef; --cc-green:#165b35;\n  --cc-orange:#c2410c; --cc-radius:16px;\n  --cc-shadow:0 4px 18px rgba(16,31,54,.055);\n}\n#appRoot, .ksseo, .infra-page, .mk, .ks-cc-page {\n  font-family:var(--ks-font,-apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"Segoe UI\",Roboto,Arial,sans-serif);\n  -webkit-font-smoothing:antialiased;\n}\n#appRoot button, #appRoot input, #appRoot select, #appRoot textarea,\n.ksseo button, .ksseo input, .ksseo select, .ksseo textarea,\n.infra-page button, .infra-page input, .infra-page select,\n.mk button, .mk input, .mk select,\n.ks-cc-page button, .ks-cc-page input, .ks-cc-page select {\n  font-family:inherit;\n}\n#appRoot :is(a,button,input,select,textarea):focus-visible,\n.ksseo :is(a,button,input,select,textarea):focus-visible,\n.infra-page :is(a,button,input,select,textarea):focus-visible,\n.mk :is(a,button,input,select,textarea):focus-visible,\n.ks-cc-page :is(a,button,input,select,textarea):focus-visible {\n  outline:3px solid #155eef!important;outline-offset:2px!important;\n}\n#appRoot .top, #appRoot .card, #appRoot .panel {\n  border-color:var(--cc-line);\n}\n#appRoot .muted, #appRoot .account.muted {color:#475569}\n#appRoot .biz-pill.recond {background:var(--cc-orange);color:#fff}\n#appRoot .biz-pill.proton {background:#154cbe;color:#fff}\n#appRoot .nav button.active, #appRoot .bottom-nav button.active {\n  font-weight:750;\n}\n#appRoot :is(button,input,select,textarea) {min-height:44px}\n#appRoot .ai-cc-nav-top {border-left-color:var(--cc-navy)!important;background:var(--cc-soft)!important;color:var(--cc-ink)!important}\n#appRoot .ai-cc-nav-top:focus-visible {outline:3px solid var(--cc-blue)}\n/* SEO: local embedded styles arrive earlier/later depending on script timing.\n * Increased selector specificity prevents generic h1/button rules from overriding legibility. */\n#appRoot .ksseo, .ksseo.ksseo {color:var(--cc-ink);line-height:1.5}\n#appRoot .ksseo .ksseo-head, .ksseo.ksseo .ksseo-head {\n  background:var(--cc-navy);color:#fff;border:1px solid #0c1728;\n  box-shadow:var(--cc-shadow);border-radius:20px;\n}\n#appRoot .ksseo .ksseo-head h1, .ksseo.ksseo .ksseo-head h1 {\n  color:#fff!important;font-size:clamp(23px,5vw,32px);font-weight:800;letter-spacing:-.035em;\n}\n#appRoot .ksseo .ksseo-head p, .ksseo.ksseo .ksseo-head p {color:#e3ebf6!important;font-size:14px;line-height:1.5}\n#appRoot .ksseo .ksseo-switch button, .ksseo.ksseo .ksseo-switch button {\n  background:#e8edf5;color:var(--cc-ink);border:1px solid #cad4e1;\n  min-height:50px;border-radius:12px;font-size:15px;font-weight:700;\n}\n#appRoot .ksseo .ksseo-switch button.active, .ksseo.ksseo .ksseo-switch button.active {\n  background:var(--cc-navy);color:#fff;border-color:var(--cc-navy);\n}\n#appRoot .ksseo .ksseo-tabs button, .ksseo.ksseo .ksseo-tabs button {\n  background:#e8edf5;color:var(--cc-ink);border:1px solid #c9d3e2;\n  font-size:14px;min-height:46px;font-weight:700;border-radius:12px;\n}\n#appRoot .ksseo .ksseo-tabs button.active, .ksseo.ksseo .ksseo-tabs button.active {\n  background:var(--cc-blue);color:#fff;border-color:var(--cc-blue);\n}\n#appRoot .ksseo .ksseo-next, .ksseo.ksseo .ksseo-next {\n  background:#eaf6ef;border:1px solid #a5d6b8;border-radius:16px;color:#123821;\n}\n#appRoot .ksseo .ksseo-next b, .ksseo.ksseo .ksseo-next b {color:var(--cc-green);font-size:13px}\n#appRoot .ksseo .ksseo-next span, .ksseo.ksseo .ksseo-next span {color:#123821;font-size:15px}\n#appRoot .ksseo :is(.ksseo-metric,.ksseo-box), .ksseo.ksseo :is(.ksseo-metric,.ksseo-box) {\n  border:1px solid var(--cc-line);border-radius:var(--cc-radius);\n  background:#fff;color:var(--cc-ink);box-shadow:var(--cc-shadow);\n}\n#appRoot .ksseo .ksseo-muted, .ksseo.ksseo .ksseo-muted,\n#appRoot .ksseo .ksseo-metric small, .ksseo.ksseo .ksseo-metric small {color:#485b73}\n#appRoot .ksseo :is(input,select,textarea),.ksseo.ksseo :is(input,select,textarea) {\n  background:#fff;color:var(--cc-ink);border-color:#9aabc1;font-size:16px;\n}\n#appRoot .ksseo :is(button,.ksseo-btn),.ksseo.ksseo :is(button,.ksseo-btn) {min-height:44px}\n/* Infrastructure uses exactly the same navy headers, muted text and panel outlines. */\n.infra-page .infra-hero{background:var(--cc-navy);color:#fff;border:1px solid #0c1728;border-radius:20px}\n.infra-page .infra-hero h1{color:#fff!important;font-weight:800}\n.infra-page .infra-hero p{color:#e3ebf6!important}\n.infra-page :is(.infra-card,.infra-panel,.infra-box){border-color:var(--cc-line);border-radius:var(--cc-radius)}\n/* Marketing intentionally retains its dark surfaces and readable light text. */\n.mk {--mk-text:#eff6ff;--mk-muted:#b4c4d9}\n.mk .mk-top h1{color:#fff!important;font-weight:800}\n.mk .mk-sub,.mk label{color:#cedaf0}\n.mk :is(input,select,textarea){color:#f8fbff;border-color:#60718a}\n.mk :is(input,select,textarea)::placeholder{color:#b6c5d8}\n/* AI Sales Control Center is a separate HTML document, so it receives this stylesheet directly. */\nhtml:not([data-ks-v6]):has(body.ks-cc-page):not([data-theme=dark]) {\n --bg:#f4f6fa;--panel:#fff;--soft:#edf2f8;--line:#cfd7e4;\n --fg:#101f36;--mut:#475569;--acc:#155eef;--accbg:#e7efff;\n --ok:#165b35;--okbg:#e7f5eb;--warn:#805200;--warnbg:#fff1d6;\n --bad:#9f2b1e;--badbg:#fdeae6;--r:14px;\n}\nbody.ks-cc-page{font-family:var(--ks-font,-apple-system,BlinkMacSystemFont,\"SF Pro Text\",\"Segoe UI\",Roboto,Arial,sans-serif)}\n.ks-cc-page header{background:var(--bg)}\n.ks-cc-page h1{font-weight:800;letter-spacing:-.025em}\n.ks-cc-page .card{border:1px solid var(--line);border-radius:16px;box-shadow:var(--cc-shadow)}\n.ks-cc-page :is(button,.tabs button){border-radius:12px;font-weight:650}\n.ks-cc-page :is(.sub,.muted){color:var(--mut)}\n.ks-cc-page #gate{border:1px solid var(--cc-line);background:var(--cc-panel);color:var(--cc-ink)}\n.ks-cc-page #gate .gate,.ks-cc-page #gate #go{display:none!important}\n.ks-cc-page #cc-sso-message{color:#30445f;font-size:15px;line-height:1.55}\n.ks-cc-page #cc-back{color:#155eef;text-decoration:underline;text-underline-offset:3px}\n@media(max-width:600px){\n  .ksseo.ksseo .ksseo-tabs{gap:7px}\n  .ksseo.ksseo .ksseo-tabs button{padding:0 14px;min-height:46px}\n  .ksseo.ksseo .ksseo-grid{gap:9px}\n  .ks-cc-page .wrap{padding-inline:14px}\n}\n/* AUDIT_20261027 tap targets */\n.ks-cc-page #cc-back{display:inline-flex;align-items:center;min-height:44px;padding:0 4px}\n.ks-cc-page .seg button,.ks-cc-page .filters button,.ks-cc-page .tabs button{min-height:44px}\n@media(prefers-reduced-motion:reduce){\n  #appRoot *, .ksseo *, .infra-page *, .mk *, .ks-cc-page * {scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}\n}\n";
