function patchRestoreFailure(script) {
 const old="  }catch(e){clearSession()}\n })();\n})();";
 const fixed="  }catch(e){if([400,401,403].includes(e?.status)){clearSession()}else{state.session=null;state.leads=null;state.threads=null;state.thread=null;document.body.classList.add('authed');$('view').replaceChildren();const box=document.createElement('section');box.className='card';const text=document.createElement('p');text.textContent='Sambungan sesi terganggu. Cuba lagi untuk sahkan akses.';const retry=document.createElement('button');retry.type='button';retry.textContent='Cuba lagi';retry.onclick=()=>location.reload();box.append(text,retry);$('view').append(box)}}/* KS_V6_RESTORE_RETRY */\n })();\n})();";
 if(script.includes('KS_V6_RESTORE_RETRY'))return script;
 if(script.split(old).length!==2)throw Error('Unsupported RC4 session restoration baseline');
 return script.replace(old,fixed);
}
function patchWorkspaceRestore(script) {
 if(script.includes('KS_V6_DEEP_RESTORE'))return script;
 const old="   await load();\n   let ws=null;try{ws=sessionStorage.getItem(WSK)}catch{}\n   if(ws==='recond'||ws==='proton')await switchWorkspace(ws,'dashboard');\n   await applyDeep();";
 const fixed="   const requestedDeep=deepPending;/* KS_V6_DEEP_RESTORE */\n   await load();\n   if(!requestedDeep){let ws=null;try{ws=sessionStorage.getItem(WSK)}catch{}if(ws==='recond'||ws==='proton')await switchWorkspace(ws,'dashboard')}\n   await applyDeep();";
 const stripped="if(deepPending){try{history.replaceState(null,'',location.pathname)}catch{}}";
 if(script.split(old).length!==2||script.split(stripped).length!==2)throw Error('Unsupported RC4 workspace restore baseline');
 return script.replace(old,fixed).replace(stripped,'/* KS_V6_KEEP_DEEP_URL: preserve validated workspace/page links across reload. */');
}

const existingV6Worker = {
 async fetch(request,env,ctx){
  const u=new URL(request.url);
  if(u.pathname==='/ks-v6.css'||u.pathname==='/ks-v6.js')return new Response(u.pathname.endsWith('.css')?V6_CSS:V6_JS,{headers:{'content-type':u.pathname.endsWith('.css')?'text/css;charset=utf-8':'application/javascript;charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','x-robots-tag':'noindex,nofollow'}});
  const r=await productionBaseline.fetch(request,env,ctx);
  if(u.pathname==='/rc4.js'&&r.ok&&request.method!=='HEAD'){
   const h=new Headers(r.headers);for(const k of ['content-length','content-encoding','etag'])h.delete(k);
   return new Response(patchWorkspaceRestore(patchRestoreFailure(await r.text())),{status:r.status,headers:h});
  }
  if(request.method==='HEAD'||!r.ok||!r.headers.get('content-type')?.includes('text/html'))return r;
  let html=await r.text();
  if(u.pathname==='/'||u.pathname==='/index.html')html=patchRootSession(html);
  // A SPA missing-asset response must never receive UI code as if it were a real JS/CSS asset.
  if(!['/','/index.html','/ai-sales-v1','/ai-sales-command-center','/takaful-keluarga','/takaful-keluarga/','/takaful-keluarga/ai-persona','/takaful-keluarga/seo','/takaful-keluarga/seo/'].includes(u.pathname))return new Response(html,{status:r.status,headers:r.headers});
  const out=html.replace('<html ','<html data-ks-v6="1" ').replace('</head>','<link rel="stylesheet" href="/ks-v6.css"></head>').replace('</body>','<script src="/ks-v6.js"></script></body>');
  const h=new Headers(r.headers);for(const k of ['content-length','content-encoding','etag'])h.delete(k);h.set('cache-control','private,no-store');h.set('x-ks-ui','v6-candidate');
  return new Response(out,{status:r.status,headers:h});
 }
};

// KS_PUBLIC_DAWN_20261101: public landing and alias for the existing dashboard.
const PUBLIC_DAWN_HTML = "<!doctype html>\n<html lang=\"ms\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#16243a\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Kerja Sendiri</title>\n<style>\n/* Layout: satu skrin penuh, pemandangan di belakang, nama di tengah, tab terapung untuk navigasi.\n   Mudah ubah: LOGIN_URL di hujung fail. */\n:root{\n  --ink:#ffffff;\n  --ink-soft:rgba(255,255,255,.78);\n  --night:#16243a;\n  --glass:rgba(22,36,58,.52);\n  --glass-line:rgba(255,255,255,.22);\n  --pill:#ffffff;\n  --pill-ink:#10192a;\n  --focus:#9cc9ff;\n  --font:-apple-system,BlinkMacSystemFont,\"SF Pro Display\",\"SF Pro Text\",\"Segoe UI\",Roboto,\"Helvetica Neue\",Arial,sans-serif;\n  --tab-h:52px;\n}\n*{box-sizing:border-box}\nhtml,body{height:100%;margin:0}\nbody{\n  background:var(--night);color:var(--ink);font-family:var(--font);\n  -webkit-font-smoothing:antialiased;-webkit-tap-highlight-color:transparent;\n  overflow:hidden;\n}\n.scene{position:fixed;inset:0;display:block;width:100%;height:100%}\n.scrim{position:fixed;inset:0;pointer-events:none;\n  background:linear-gradient(180deg,rgba(10,18,32,.55) 0%,rgba(10,18,32,.18) 38%,rgba(10,18,32,0) 62%)}\nmain{\n  position:relative;z-index:1;height:100%;\n  display:flex;flex-direction:column;align-items:center;justify-content:center;gap:28px;\n  padding-block:max(24px,env(safe-area-inset-top,0px)) calc(var(--tab-h) + 64px + env(safe-area-inset-bottom,0px));\n  padding-left:max(24px,env(safe-area-inset-left,0px));\n  padding-right:max(24px,env(safe-area-inset-right,0px));\n  text-align:center;\n  transform:translateY(-6vh);\n}\nh1{\n  margin:0;font-weight:600;letter-spacing:-.035em;line-height:1.02;\n  font-size:clamp(44px,9vw,96px);text-wrap:balance;\n  text-shadow:0 2px 28px rgba(8,14,26,.35);\n}\n.cta{\n  display:inline-flex;align-items:center;justify-content:center;\n  min-height:48px;padding:0 28px;border-radius:999px;\n  background:var(--pill);color:var(--pill-ink);\n  font:500 17px/1 var(--font);letter-spacing:-.01em;text-decoration:none;\n  transition:transform .18s ease,background .18s ease;\n}\n.cta:hover{background:#eef3fa}\n.cta:active{transform:scale(.97)}\n\n/* Tab terapung: bawah pada telefon, atas-tengah pada desktop */\n.tabs{\n  position:fixed;z-index:5;left:50%;transform:translateX(-50%);\n  bottom:calc(16px + env(safe-area-inset-bottom,0px));\n  display:flex;gap:4px;padding:4px;border-radius:999px;\n  background:var(--glass);border:1px solid var(--glass-line);\n  box-shadow:0 10px 30px rgba(6,12,24,.28);\n}\n@supports ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))){\n  .tabs{-webkit-backdrop-filter:saturate(180%) blur(22px);backdrop-filter:saturate(180%) blur(22px)}\n}\n.tabs a{\n  display:inline-flex;align-items:center;justify-content:center;\n  min-width:96px;height:44px;padding:0 20px;white-space:nowrap;border-radius:999px;\n  color:var(--ink);text-decoration:none;font:500 15px/1 var(--font);letter-spacing:-.01em;\n  transition:background .18s ease,color .18s ease;\n}\n.tabs a[aria-current=\"page\"]{background:rgba(255,255,255,.2)}\n.tabs a.login{background:var(--pill);color:var(--pill-ink)}\n.tabs a:not(.login):hover{background:rgba(255,255,255,.14)}\na:focus-visible{outline:3px solid var(--focus);outline-offset:2px}\n\n@media (min-width:900px){\n  .tabs{bottom:auto;top:calc(20px + env(safe-area-inset-top,0px))}\n  main{transform:translateY(0);padding-block:max(24px,env(safe-area-inset-top,0px));}\n}\n@media (max-width:380px){.tabs a{min-width:80px;padding:0 16px}}\n\n@media (prefers-reduced-motion:no-preference){\n  main{animation:rise .9s cubic-bezier(.2,.7,.2,1) both}\n  .tabs{animation:fade 1s .25s ease both}\n  .far{animation:drift 60s ease-in-out infinite alternate}\n}\n@keyframes rise{from{opacity:0;translate:0 14px}to{opacity:1;translate:0 0}}\n@keyframes fade{from{opacity:0}to{opacity:1}}\n@keyframes drift{from{transform:translateX(-12px)}to{transform:translateX(12px)}}\n</style>\n<script>\n(function(){try{var s=JSON.parse(sessionStorage.getItem('rc4.sess')||'null');if((s&&typeof s.r==='string'&&s.r)||location.search)location.replace('/masuk'+location.search+location.hash)}catch(e){if(location.search)location.replace('/masuk'+location.search+location.hash)}})();\n</script></head>\n<body>\n\n<!-- Pemandangan: subuh di kawasan tinggi. SVG sendiri, tiada imej luar. -->\n<svg class=\"scene\" viewBox=\"0 0 1600 900\" preserveAspectRatio=\"xMidYMax slice\" role=\"img\" aria-label=\"Pemandangan pergunungan ketika subuh\">\n  <defs>\n    <linearGradient id=\"sky\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n      <stop offset=\"0\" stop-color=\"#14213a\"/>\n      <stop offset=\".45\" stop-color=\"#3a4f7a\"/>\n      <stop offset=\".72\" stop-color=\"#d98f6e\"/>\n      <stop offset=\"1\" stop-color=\"#f6c58f\"/>\n    </linearGradient>\n    <radialGradient id=\"sun\" cx=\"1080\" cy=\"560\" r=\"380\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0\" stop-color=\"#fff1d0\" stop-opacity=\".95\"/>\n      <stop offset=\".35\" stop-color=\"#ffd9a6\" stop-opacity=\".45\"/>\n      <stop offset=\"1\" stop-color=\"#ffd9a6\" stop-opacity=\"0\"/>\n    </radialGradient>\n    <linearGradient id=\"r1\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#8a8fb0\"/><stop offset=\"1\" stop-color=\"#d6a98f\"/></linearGradient>\n    <linearGradient id=\"r2\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#5f6690\"/><stop offset=\"1\" stop-color=\"#a98a97\"/></linearGradient>\n    <linearGradient id=\"r3\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#3f4870\"/><stop offset=\"1\" stop-color=\"#6b6384\"/></linearGradient>\n    <linearGradient id=\"r4\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#26304f\"/><stop offset=\"1\" stop-color=\"#3a3d5c\"/></linearGradient>\n    <linearGradient id=\"r5\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\"><stop offset=\"0\" stop-color=\"#151c33\"/><stop offset=\"1\" stop-color=\"#1b2138\"/></linearGradient>\n    <filter id=\"grain\" x=\"0\" y=\"0\" width=\"100%\" height=\"100%\">\n      <feTurbulence type=\"fractalNoise\" baseFrequency=\".9\" numOctaves=\"2\" seed=\"7\" result=\"n\"/>\n      <feColorMatrix type=\"saturate\" values=\"0\"/>\n      <feComponentTransfer><feFuncA type=\"linear\" slope=\".05\"/></feComponentTransfer>\n    </filter>\n  </defs>\n  <rect width=\"1600\" height=\"900\" fill=\"url(#sky)\"/>\n  <rect width=\"1600\" height=\"900\" fill=\"url(#sun)\"/>\n  <g class=\"far\">\n    <path fill=\"url(#r1)\" d=\"M-40 640 L120 560 C200 520 250 520 330 570 L470 470 C520 436 560 440 610 480 L760 590 C820 560 880 520 940 540 L1100 610 C1170 560 1230 470 1300 450 C1350 438 1400 470 1440 510 L1660 640 L1660 900 L-40 900Z\"/>\n  </g>\n  <path fill=\"url(#r2)\" d=\"M-40 700 L90 640 C170 600 230 560 310 600 L420 660 C500 590 560 520 640 500 C700 486 740 520 790 570 L900 660 C980 620 1060 590 1140 620 L1280 560 C1340 536 1400 560 1460 600 L1660 700 L1660 900 L-40 900Z\"/>\n  <path fill=\"url(#r3)\" d=\"M-40 760 L140 690 C220 660 300 690 380 730 L520 700 C600 670 660 640 740 670 L880 740 C960 700 1040 680 1120 700 L1300 660 C1380 640 1460 680 1520 720 L1660 760 L1660 900 L-40 900Z\"/>\n  <path fill=\"url(#r4)\" d=\"M-40 810 C100 770 220 760 340 790 C460 820 560 790 680 770 C800 750 900 790 1020 800 C1160 812 1260 770 1380 770 C1480 770 1560 790 1660 810 L1660 900 L-40 900Z\"/>\n  <path fill=\"url(#r5)\" d=\"M-40 860 C120 836 260 832 400 852 C540 872 640 850 780 842 C920 834 1040 862 1180 862 C1320 862 1460 836 1660 850 L1660 900 L-40 900Z\"/>\n  <rect width=\"1600\" height=\"900\" filter=\"url(#grain)\"/>\n</svg>\n<div class=\"scrim\" aria-hidden=\"true\"></div>\n\n<main>\n  <h1>Kerja Sendiri</h1>\n  <a class=\"cta\" href=\"/masuk\" data-login>Log masuk</a>\n</main>\n\n<nav class=\"tabs\" aria-label=\"Navigasi utama\">\n  <a href=\"/\" aria-current=\"page\">Utama</a>\n  <a href=\"/masuk\" class=\"login\" data-login>Log masuk</a>\n</nav>\n\n<script>\n/* Tukar sekali di sini jika laluan log masuk lain. Lihat DEPLOY.md. */\nvar LOGIN_URL = \"/masuk\";\ndocument.querySelectorAll(\"[data-login]\").forEach(function(a){a.setAttribute(\"href\",LOGIN_URL)});\n</script>\n</body>\n</html>";
export default {
 async fetch(request,env,ctx){
  const u=new URL(request.url);
  const isDocument=['GET','HEAD'].includes(request.method);
  if(u.protocol==='https:'&&isDocument&&['/','/index.html'].includes(u.pathname)){
   const baseline=await productionBaseline.fetch(new Request(new URL('/healthz',u),request),env,ctx);
   const h=new Headers(baseline.headers);
   for(const k of ['content-length','content-encoding','etag'])h.delete(k);
   h.set('content-type','text/html;charset=utf-8');h.set('cache-control','private,no-store');h.set('x-ks-ui','public-dawn');
   return new Response(request.method==='HEAD'?null:PUBLIC_DAWN_HTML,{headers:h});
  }
  if(u.pathname==='/masuk/'||u.pathname==='/masuk.html'){
   u.pathname='/masuk';return Response.redirect(u.toString(),302);
  }
  if(u.pathname==='/masuk'&&isDocument){
   const target=new URL(u);target.pathname='/';
   const r=await existingV6Worker.fetch(new Request(target,request),env,ctx);
   if(!r.ok||request.method==='HEAD')return r;
   const html=await r.text();
   // Original login form and handlers; only open the existing dialog for signed-out visitors.
   const open='<script>(function(){var r=null;try{r=JSON.parse(sessionStorage.getItem("rc4.sess")||"null")}catch(e){}if(!r||!r.r){var d=document.getElementById("loginDialog");if(d&&!d.open){d.showModal();document.getElementById("email")?.focus()}}})();</script>';
   const h=new Headers(r.headers);for(const k of ['content-length','content-encoding','etag'])h.delete(k);
   return new Response(html.replace('</body>',open+'</body>'),{status:r.status,headers:h});
  }
  const r=await existingV6Worker.fetch(request,env,ctx);
  if(u.pathname==='/ks-v6.js'&&r.ok&&request.method!=='HEAD'){
   // Let the existing navigation controller recognise the dashboard alias.
   const js=(await r.text()).replaceAll("u.pathname==='/'","(u.pathname==='/'||u.pathname==='/masuk')").replaceAll("location.pathname==='/'","(location.pathname==='/'||location.pathname==='/masuk')");
   const h=new Headers(r.headers);h.delete('content-length');return new Response(js,{headers:h});
  }
  return r;
 }
};
